/**
 * The real PXO legal documents, bilingual.
 *
 * Converted mechanically from the dialogs in docs/looks/pxo_octubre.html by a
 * one-off script, then verified character-for-character against that file —
 * nothing here was retyped or summarised, because the wording is the deliverable.
 * Keep it that way: re-run the conversion against a new design drop rather than
 * hand-editing, and have legal confirm any change to the text.
 *
 * Structured rather than a single string because the privacy notice contains a
 * three-column table that plain `whitespace-pre-wrap` cannot render legibly.
 *
 * Loaded on demand (see LegalDocumentModal) so ~58 KB of legal prose stays out
 * of the landing page's initial bundle.
 *
 * NOT READY TO PUBLISH — the privacy notice still carries two unfilled fields
 * from the source document, in both languages:
 *   - "Last updated: [publication date]" / "[fecha de publicación]"
 *   - "with its address at [address]" / "con domicilio en [domicilio]"
 * They are reproduced verbatim rather than guessed. A privacy notice without a
 * date or a controller address is incomplete under the LFPDPPP it cites, so
 * these need real values before the footer link goes live in production.
 * The terms document is complete (June 2026).
 */

export type LegalRun = { t: string; b?: true };

export type LegalNode =
  | { type: 'h3' | 'p'; runs: LegalRun[] }
  | { type: 'ul' | 'ol'; items: LegalRun[][] }
  | { type: 'table'; head: LegalRun[][]; rows: LegalRun[][][] };

export interface LegalDocumentContent {
  title: string;
  nodes: LegalNode[];
}

/** Which document a link opens. Distinct from the *acceptance* documents in
 *  termsContent.ts: these are informational and gate nothing. */
export type LegalDocumentKey = 'terms' | 'privacy';

